@Service
public class OrderService {
    private final PaymentGateway paymentGateway;
    private final InventoryRepository inventoryRepo;

    // Constructor injection - preferred approach
    @Autowired
    public OrderService(PaymentGateway paymentGateway, 
                        InventoryRepository inventoryRepo) {
        this.paymentGateway = paymentGateway;  // Spring injects these
        this.inventoryRepo = inventoryRepo;
    }

    public void processOrder(Order order) {
        if (inventoryRepo.checkStock(order.getItemId())) {
            paymentGateway.charge(order.getAmount());
            inventoryRepo.decrementStock(order.getItemId());
        }
    }
}

@Repository
class InventoryRepository { /* bean exists in context */ }

